_BASE_DIR = os.path.dirname(os.path.abspath(__file__))
WF_DIR = os.path.join(_BASE_DIR, "wireframes")

WF = {}
try:
    from make_wireframes import generate_all as _gen_wireframes, OUT as WF_DIR
    WF = _gen_wireframes()
except Exception as _wf_err:
    print("wireframes skipped:", _wf_err)

def wf_path(key):
    p = WF.get(key)
    if not p:
        p = os.path.join(WF_DIR, key + ".png")
    return p

def wf_ok(key):
    return os.path.exists(wf_path(key))

def add_wf_image(doc, key, caption, width_cm=9.0, new_page=True):
    """Insert a wireframe image (typically on its own page) into the Word document."""
    if not wf_ok(key):
        return
    if new_page:
        doc.add_page_break()
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(4)
    p.add_run().add_picture(wf_path(key), width=Cm(width_cm))
    c = doc.add_paragraph()
    c.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = c.add_run(caption)
    r.font.name = "Vazirmatn"
    r.font.size = Pt(9.5)
    r.font.bold = True
    r.font.color.rgb = RGBColor(0x7A, 0x84, 0x96)
    doc.add_paragraph()

def set_cell_shading(cell, color):
    shading_elm = OxmlElement('w:shd')
    shading_elm.set(qn('w:fill'), color)
    shading_elm.set(qn('w:val'), 'clear')
    cell._tc.get_or_add_tcPr().append(shading_elm)

def add_heading_rtl(doc, text, size=16, color=NAVY):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    run = p.add_run(text)
    run.font.name = 'Vazirmatn'
    run.font.size = Pt(size)
    run.font.bold = True
    run.font.color.rgb = color
    return p

def add_paragraph_rtl(doc, text, size=11, bold=False, color=BLACK):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    run = p.add_run(text)
    run.font.name = 'Vazirmatn'
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.color.rgb = color
    return p

def add_table_rtl(doc, headers, rows, col_widths=None):
    table = doc.add_table(rows=1 + len(rows), cols=len(headers))
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    table.style = 'Table Grid'
    
    for i, header in enumerate(headers):
        cell = table.rows[0].cells[i]
        cell.text = ""
        p = cell.paragraphs[0]
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        run = p.add_run(header)
        run.font.name = 'Vazirmatn'
        run.font.size = Pt(10)
        run.font.bold = True
        run.font.color.rgb = WHITE
        set_cell_shading(cell, "1B2A4A")
    
    for i, row in enumerate(rows):
        for j, cell_text in enumerate(row):
            cell = table.rows[i + 1].cells[j]
            cell.text = ""
            p = cell.paragraphs[0]
            p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            run = p.add_run(str(cell_text))
            run.font.name = 'Vazirmatn'
            run.font.size = Pt(9)
            run.font.color.rgb = BLACK
            if i % 2 == 0:
                set_cell_shading(cell, "F5F0E8")
    
    return table

MD_PATH = r"C:\Users\Lucifer\Documents\Default Project\project-document.md"

def load_changelog():
    """Read the changelog table straight from project-document.md.

    The markdown file is the single source of truth for the change log, so the
    Word and PDF copies can never drift away from it.
    Returns a list of [date, change, note] rows (markdown decorations stripped).
    """
    try:
        with open(MD_PATH, "r", encoding="utf-8") as fh:
            lines = fh.read().split("\n")
    except Exception as exc:
        print("changelog skipped: %s" % exc)
        return []
    start = None
    for i, line in enumerate(lines):
        if line.startswith("## ") and "تاریخچه تغییرات" in line:
            start = i
    if start is None:
        print("changelog skipped: chapter not found")
        return []
    rows = []
    for line in lines[start + 1:]:
        if line.startswith("## "):
            break
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) < 3:
            continue
        if set(cells[0]) <= set("-: "):
            continue
        if cells[0] == "تاریخ":
            continue
        rows.append([c.replace("**", "").replace("`", "").strip() for c in cells[:3]])
    return rows

