def create_pdf():
    class PDF(FPDF):
        def __init__(self):
            super().__init__()
            self.set_auto_page_break(auto=True, margin=20)
            self.add_font("Vazirmatn", "", FONT_REGULAR)
            self.add_font("Vazirmatn", "B", FONT_BOLD)

        def header(self):
            if self.page_no() == 1:
                return
            self.set_fill_color(27, 42, 74)
            self.rect(0, 0, 210, 15, "F")
            self.set_text_color(255, 255, 255)
            self.set_font("Vazirmatn", "B", 8)
            self.set_xy(10, 5)
            self.cell(0, 5, fa("AMPET | مستند پروژه"), align="C")
            self.set_text_color(44, 44, 44)
            self.ln(20)

        def footer(self):
            self.set_y(-15)
            self.set_fill_color(245, 240, 232)
            self.rect(0, self.get_y(), 210, 15, "F")
            self.set_text_color(27, 42, 74)
            self.set_font("Vazirmatn", "", 7)
            self.set_x(10)
            self.cell(0, 5, fa(f"صفحه {self.page_no()}"), align="C")
            self.set_text_color(44, 44, 44)

        def chapter_title(self, title):
            self.set_fill_color(27, 42, 74)
            self.rect(10, self.get_y(), 190, 12, "F")
            self.set_text_color(255, 255, 255)
            self.set_font("Vazirmatn", "B", 12)
            self.set_xy(15, self.get_y() + 2)
            self.cell(0, 8, fa(title), align="R")
            self.set_text_color(44, 44, 44)
            self.ln(16)

        def sub_title(self, title):
            self.set_fill_color(201, 169, 110)
            self.rect(10, self.get_y(), 190, 8, "F")
            self.set_text_color(255, 255, 255)
            self.set_font("Vazirmatn", "B", 10)
            self.set_xy(15, self.get_y() + 1)
            self.cell(0, 6, fa(title), align="R")
            self.set_text_color(44, 44, 44)
            self.ln(12)

        def body_text(self, text):
            self.set_font("Vazirmatn", "", 9)
            self.set_text_color(44, 44, 44)
            self.multi_cell(0, 6, fa(text), align="R")
            self.ln(2)

        def bullet_point(self, text):
            self.set_font("Vazirmatn", "", 9)
            self.set_text_color(44, 44, 44)
            self.set_x(15)
            self.cell(5, 6, "-", align="R")
            self.multi_cell(0, 6, fa(text), align="R")
            self.ln(1)

        def add_table(self, headers, rows, col_widths=None):
            if col_widths is None:
                col_widths = [190 / len(headers)] * len(headers)
            self.set_fill_color(27, 42, 74)
            self.set_text_color(255, 255, 255)
            self.set_font("Vazirmatn", "B", 8)
            for i, header in enumerate(headers):
                self.cell(col_widths[i], 8, fa(header), align="C", border=1, fill=True)
            self.ln()
            self.set_text_color(44, 44, 44)
            self.set_font("Vazirmatn", "", 8)
            fill = False
            for row in rows:
                if fill:
                    self.set_fill_color(245, 240, 232)
                for i, cell in enumerate(row):
                    self.cell(col_widths[i], 7, fa(str(cell)), align="C", border=1, fill=fill)
                self.ln()
                fill = not fill
            self.ln(4)

        def add_table_wrapped(self, headers, rows, col_widths=None,
                              font_size=7.5, line_h=4.6, pad=1.2):
            """Table whose body cells wrap instead of overflowing the page."""
            if col_widths is None:
                col_widths = [190 / len(headers)] * len(headers)
            x0 = self.l_margin

            def draw_header():
                self.set_fill_color(27, 42, 74)
                self.set_text_color(255, 255, 255)
                self.set_font("Vazirmatn", "B", font_size)
                y = self.get_y()
                x = x0
                for i, head in enumerate(headers):
                    self.set_xy(x, y)
                    self.cell(col_widths[i], 7, fa(str(head)), align="C", border=1, fill=True)
                    x += col_widths[i]
                self.set_xy(x0, y + 7)
                self.set_text_color(44, 44, 44)

            def line_count(txt, width):
                self.set_font("Vazirmatn", "", font_size)
                lines = self.multi_cell(width - 2 * pad, line_h, fa(str(txt)),
                                        dry_run=True, output="LINES", align="R")
                return max(1, len(lines))

            draw_header()
            fill = False
            for row in rows:
                needed = max(line_count(c, col_widths[i]) for i, c in enumerate(row))
                h = needed * line_h + 1.6
                if self.get_y() + h > self.page_break_trigger:
                    self.add_page()
                    draw_header()
                y = self.get_y()
                for i, value in enumerate(row):
                    x = x0 + sum(col_widths[:i])
                    if fill:
                        self.set_fill_color(245, 240, 232)
                        self.rect(x, y, col_widths[i], h, style="DF")
                    self.rect(x, y, col_widths[i], h)
                    self.set_xy(x + pad, y + 0.8)
                    self.multi_cell(col_widths[i] - 2 * pad, line_h, fa(str(value)),
                                    align="R", new_x=XPos.RIGHT, new_y=YPos.TOP)
                self.set_xy(x0, y + h)
                fill = not fill
            self.ln(4)

    pdf = PDF()
    pdf.add_page()

    def pdf_wf(key, caption, tail_break=False):
        """Insert a wireframe image on its own PDF page."""
        if not wf_ok(key):
            return
        pdf.add_page()
        pdf.chapter_title(caption)
        w = 98
        pdf.image(wf_path(key), x=(210 - w) / 2.0, y=pdf.get_y() + 2, w=w)
        if tail_break:
            pdf.add_page()

